    fn trace_written_after_paste_not_before() {
        let sink = RecordingSink::new();
        let mut t = DictationTrace::new(7, "test-engine");
        t.audio_ms = 1200;
        t.mark(|s, now| s.t_hotkey_down = Some(now));
