        let mk = |engine: &str, total_ms: u64| -> DictationTrace {
            let mut t = DictationTrace::new(1, engine);
            t.audio_ms = 1_500;
            t.t_hotkey_up = Some(0);
            t.t_text_pipeline_end = Some(total_ms * 1000 - 100_000);
            t.t_paste_sent = Some(total_ms * 1000);
